// Valider les parametres requis
const input = $input.first().json;
const body = input.body || input;

const projectId = body.project_id || null;
const discordUserId = body.discord_user_id || null;
const planId = body.plan_id || null;
const customerEmail = body.customer_email || null;

const errors = [];
if (!projectId) errors.push('project_id');
if (!discordUserId) errors.push('discord_user_id');
if (!planId) errors.push('plan_id');

if (errors.length > 0) {
  return [{
    json: {
      valid: false,
      error: {
        code: 400,
        message: `Parametres requis manquants: ${errors.join(', ')}`,
        status: 'BAD_REQUEST'
      }
    }
  }];
}

// Valider le format du plan_id
if (!planId.startsWith('price_')) {
  return [{
    json: {
      valid: false,
      error: {
        code: 400,
        message: 'plan_id doit etre un ID de prix Stripe (price_xxx)',
        status: 'BAD_REQUEST'
      }
    }
  }];
}

// Valider le format de l'email si fourni
if (customerEmail && !customerEmail.includes('@')) {
  return [{
    json: {
      valid: false,
      error: {
        code: 400,
        message: 'customer_email doit etre une adresse email valide',
        status: 'BAD_REQUEST'
      }
    }
  }];
}

return [{
  json: {
    valid: true,
    project_id: projectId,
    discord_user_id: discordUserId,
    plan_id: planId,
    customer_email: customerEmail,
    redis_key: `project:${projectId}`
  }
}];

// Verifier que le projet existe dans Redis
const redisResult = $('Get Stripe Config (Redis)').first();
const inputData = $('Validate Input').first().json;

// Redis retourne la valeur dans propertyName, value, ou directement
const redisJson = redisResult?.json || {};
const rawValue = redisJson.propertyName || redisJson.value || redisJson;

if (!rawValue || rawValue === null) {
  return [{
    json: {
      found: false,
      error: {
        code: 404,
        message: `Projet '${inputData.project_id}' non enregistre. Le plugin doit appeler /stripe-register-project au demarrage.`,
        status: 'NOT_FOUND'
      }
    }
  }];
}

// Parser le JSON stocke dans Redis
let project;
try {
  project = typeof rawValue === 'string' ? JSON.parse(rawValue) : rawValue;
} catch (e) {
  return [{
    json: {
      found: false,
      error: {
        code: 500,
        message: `Erreur parsing Redis: ${e.message}`,
        status: 'INTERNAL_ERROR'
      }
    }
  }];
}

if (!project.stripe_key) {
  return [{
    json: {
      found: false,
      error: {
        code: 404,
        message: `Projet '${inputData.project_id}' n'a pas de cle Stripe configuree`,
        status: 'NOT_FOUND'
      }
    }
  }];
}

return [{
  json: {
    found: true,
    project_id: inputData.project_id,
    discord_user_id: inputData.discord_user_id,
    plan_id: inputData.plan_id,
    customer_email: inputData.customer_email,
    stripe_key: project.stripe_key,
    display_name: project.display_name || inputData.project_id
  }
}];

// Formater la reponse Stripe
const input = $input.first().json;
const projectData = $('Check Project').first().json;

const statusCode = input.statusCode || 200;
const data = input.body || input;

// Verifier les erreurs Stripe
if (statusCode >= 400 || data.error) {
  return [{
    json: {
      success: false,
      error: {
        code: statusCode,
        message: data.error?.message || 'Erreur Stripe API',
        status: 'STRIPE_ERROR',
        type: data.error?.type || 'api_error'
      }
    }
  }];
}

return [{
  json: {
    success: true,
    checkout_url: data.url,
    session_id: data.id,
    project_id: projectData.project_id,
    discord_user_id: projectData.discord_user_id,
    plan_id: projectData.plan_id,
    expires_at: new Date(data.expires_at * 1000).toISOString()
  }
}];
